const API_URL = process.env.REACT_APP_API_URL
  || (process.env.NODE_ENV === "development" ? "http://localhost:4000" : "");

export async function apiRequest(path, options = {}) {
  const token = localStorage.getItem("token");
  const response = await fetch(`${API_URL}/api${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...options.headers,
    },
  });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || "Request failed. Please try again.");
  return result;
}

export function saveSession({ user, token }) {
  localStorage.setItem("user", JSON.stringify(user));
  localStorage.setItem("token", token);
}

export function clearSession() {
  localStorage.removeItem("user");
  localStorage.removeItem("token");
  localStorage.removeItem("isAdminAuthenticated");
}

export function toDashboardReservation(reservation) {
  const roomNames = {
    regular: "Regular Room",
    deluxe: "Deluxe Room",
    luxury: "Luxury Room",
    event: "Event Space",
  };
  const dateOptions = { month: "short", day: "numeric", year: "numeric" };
  const customer = `${reservation.firstName} ${reservation.lastName}`;

  return {
    id: reservation.reference,
    reservationId: reservation.id,
    customer,
    init: customer.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase(),
    room: roomNames[reservation.room] || reservation.room,
    checkin: new Date(`${reservation.checkIn}T00:00:00`).toLocaleDateString("en-PH", dateOptions),
    checkout: new Date(`${reservation.checkOut}T00:00:00`).toLocaleDateString("en-PH", dateOptions),
    pax: reservation.guests,
    amount: `₱${reservation.totalAmount.toLocaleString("en-PH")}`,
    status: reservation.status,
  };
}
